#include <iostream>

int main() {
    // 输入：3。输出：可以取号。
    int number = 0;
    std::cin >> number;
    if (std::cin.fail()) {
        std::cout << "请输入整数。\n";
        return 1;
    }

    if (number < 1 || number > 4) {
        std::cout << "号码超出范围。\n";
    } else {
        std::cout << "可以取号。\n";
    }
    return 0;
}
